import type { Landmarks, ToolResult } from '../../contracts/types';
import { visibilityStats } from '../pose-metrics';
export default function analyze(input: Landmarks): ToolResult {
  if (!input || !Array.isArray(input.frames) || input.frames.length === 0) return { metrics: {}, warnings: ['no frames'], usable: false };
  const { personFrameRatio } = visibilityStats(input);
  return { metrics: { personFrameRatio }, usable: personFrameRatio > 0.6 };
}

